"""Contract checks against the vendor CLI binary shipped in vendor/bin."""
import unittest

from hbonboard.config import DEFAULTS
from hbonboard.kyc.client import IdchkClient
from hbonboard.models import KycRequest, VendorError
from tests.support import VendorHome


class IdchkClientTest(unittest.TestCase):
    def setUp(self):
        self.home = VendorHome()
        self.client = IdchkClient(DEFAULTS.with_overrides(idchk_home=self.home.path))

    def tearDown(self):
        self.home.cleanup()

    def test_submit_then_result_roundtrip(self):
        ticket = self.client.submit([
            KycRequest("T-1", "홍길동", "19900101", "01011112222"),
            KycRequest("T-2", "Kim Ara", "19851231", "01033334444"),
            KycRequest("T-3", "이도", "20000229", "0162223333"),
        ])
        self.assertTrue(ticket.job_id.startswith("J"))
        self.assertEqual(ticket.lines, 3)
        for ref in ("T-1", "T-2", "T-3"):
            self.assertIn(self.client.result(ref), (1, 2))
        self.assertEqual(self.client.job(ticket.job_id)["in"], "3")

    def test_unknown_reference_has_no_result(self):
        self.assertIsNone(self.client.result("T-404"))

    def test_malformed_line_rejects_the_file(self):
        with self.assertRaises(VendorError) as ctx:
            self.client.submit([KycRequest("T-1", "홍길동", "19900101", "021234567")])
        self.assertEqual(ctx.exception.code, "E17")
        self.assertIsNone(self.client.result("T-1"))


if __name__ == "__main__":
    unittest.main()
"""Korean mobile numbers: accept what people type, store digits only."""
import re

_MOBILE = re.compile(r"^01[016789]\d{7,8}$")


def normalize_phone(raw):
    """'010-1234-5678', '+82 10 1234 5678', '(010)1234.5678' -> '01012345678'."""
    if raw is None:
        return ""
    digits = re.sub(r"\D", "", str(raw))
    if digits.startswith("82") and len(digits) in (11, 12):
        digits = "0" + digits[2:]
    return digits


def is_mobile(digits):
    return bool(_MOBILE.match(digits or ""))


def mask_phone(digits):
    """Keep the carrier prefix and the last four digits."""
    if len(digits) < 8:
        return "*" * len(digits)
    return f"{digits[:3]}-****-{digits[-4:]}"


def display_phone(digits):
    if len(digits) == 11:
        return f"{digits[:3]}-{digits[3:7]}-{digits[7:]}"
    if len(digits) == 10:
        return f"{digits[:3]}-{digits[3:6]}-{digits[6:]}"
    return digits
"""Name helpers shared by the sign-up form and the vendor bridge."""
import unicodedata

_SPACES = {"\t", "\n", "\r", "\x0b", "\x0c", " ", "　"}


def normalize_name(text):
    """NFC-normalize, turn odd whitespace into plain spaces, collapse runs."""
    if text is None:
        return ""
    text = unicodedata.normalize("NFC", str(text))
    out = []
    for ch in text:
        if ch in _SPACES:
            ch = " "
        elif unicodedata.category(ch) in ("Cc", "Cf"):
            continue
        if ch == " " and out and out[-1] == " ":
            continue
        out.append(ch)
    return "".join(out).strip()


def mask_name(name):
    """홍길동 -> 홍*동, 이도 -> 이*, Kim Minseo -> K********o."""
    if len(name) <= 1:
        return name
    if len(name) == 2:
        return name[0] + "*"
    return name[0] + "*" * (len(name) - 2) + name[-1]


def vendor_name(name):
    """The vendor matches on the registered name without spaces."""
    return name.replace(" ", "")
"""Date helpers (ISO strings only; no time zones involved)."""
import datetime as _dt


def parse_date(value):
    raw = str(value or "").strip()
    if len(raw) == 8 and raw.isdigit():
        raw = f"{raw[:4]}-{raw[4:6]}-{raw[6:]}"
    try:
        return _dt.date.fromisoformat(raw)
    except ValueError:
        raise ValueError(f"invalid date: {value!r}") from None


def compact(iso_date):
    """2001-02-03 -> 20010203"""
    return parse_date(iso_date).strftime("%Y%m%d")


def age_on(birth, today):
    """Full years (만 나이) on `today`."""
    b = parse_date(birth)
    years = today.year - b.year
    if (today.month, today.day) < (b.month, b.day):
        years -= 1
    return years
